                'body_help' => '<strong>हमेशा उपलब्ध:</strong> [ticket_reference], [ticket_url], [ticket_subject], [ticket_status], [ticket_priority], [requester_name], [requester_first_name], [requester_email], [analyst_name], [analyst_email], [department_name], [created_date], [closed_date].<br><br><strong>विश्लेषक को भेजे जाने वाले ईमेल के लिए:</strong><br>[assigned_analyst_name], [assigned_analyst_first_name], [assigned_analyst_email] &mdash; वह विश्लेषक जिसे टिकट <em>असाइन</em> किया गया है।<br>[ticket_url_analyst] &mdash; इनबॉक्स में टिकट खोलने वाला लिंक। [ticket_url] के बजाय यही उपयोग करें, क्योंकि वह ग्राहक का अपना व्यू खोलता है और उसके लिए पोर्टल अकाउंट चाहिए।<br><br>&#9888; <strong>[analyst_name] हमेशा असाइन किया गया विश्लेषक नहीं होता।</strong> जहाँ टिकट का <em>स्वामी</em> तय है वहाँ यह स्वामी का नाम देता है, और तय न हो तो असाइन किए गए विश्लेषक पर लौट आता है &mdash; ज़्यादातर सर्विस डेस्क पर ये दो अलग-अलग लोग होते हैं। ग्राहक को यह बताने के लिए कि उनका काम कौन देख रहा है, यही सही कोड है। लेकिन जब ईमेल अभी-अभी मिले काम के बारे में <em>विश्लेषक को ही</em> भेजा जा रहा हो, तब [assigned_analyst_name] उपयोग करें।<br><br><strong>केवल कुछ ट्रिगर पर:</strong><br>[note_text] &mdash; <strong>अनुरोधकर्ता के साथ नोट साझा किया गया</strong> पर, नोट स्वयं। इसे छोड़ दें तो ईमेल सिर्फ़ इतना कहता है कि कोई अपडेट है।<br>[ticket_closed_message] &mdash; <strong>टिकट बंद हुआ</strong> पर, टिकट बंद करते समय विश्लेषक द्वारा लिखा गया एक बार का नोट। इसे जोड़ें तो उनसे यह नोट माँगा जाता है; न जोड़ें तो नहीं माँगा जाता।<br><br>HTML समर्थित है (जैसे स्टाइल किए गए बटन)।',
