            'orig_thread_help' => 'हर संदेश मर्ज किए गए टिकट की बातचीत का हिस्सा बन जाता है, यह लेबल किया हुआ कि यह किस टिकट से आया। इनलाइन पढ़ने योग्य, जवाब में कोट करने योग्य, और खोज से मिलने वाला।',
