            'ai_help' => 'मर्ज किए गए टिकट पर एक नोट जोड़ता है जो बताता है कि हर अनुरोधकर्ता ने क्या माँगा था और अब तक क्या किया जा चुका है, ताकि जो भी इसे उठाए उसे हर बातचीत पढ़नी न पड़े। इसके लिए उत्तर सफ़ाई टैब पर एक AI प्रदाता कॉन्फ़िगर होना चाहिए। इसके बिना भी मर्ज करना काम करता है।',
