            'targets_intro' => 'हर टिकट प्राथमिकता के लिए प्रतिक्रिया और समाधान समय। समय मिनट में हैं (60 = 1 घंटा, 240 = 4 घंटे, 1440 = 1 दिन)। कैलेंडर तय करता है कि घड़ी किन व्यावसायिक घंटों के हिसाब से चलेगी। उस लक्ष्य को छोड़ने के लिए खाली रखें।',
