            'collapse_quoted_help' => 'नीचे एक लंबी कोट की हुई चेन वाला छोटा जवाब लाइन गिनती के हिसाब से संक्षिप्त होते हुए भी अपठनीय होता है, इसलिए कोट किया गया इतिहास अलग से छोटा किया जाता है।',
            'collapse_remember_label' => 'मैंने जो खोला था वह याद रखें',
            'collapse_remember_help' => 'जो संदेश आप विस्तृत करते हैं वे इस डिवाइस पर विस्तृत बने रहते हैं, ताकि किसी थ्रेड पर काम हर रीफ्रेश पर खुद को पूर्ववत न करे।',
