            'team_folders_mine' => 'केवल वे टीमें जिनके वे सदस्य हैं',
            'team_folders_help' => 'केवल फ़ोल्डर सूची बदलता है - किसी का कोई टिकट दिखना बंद नहीं होता। जिस टीम के पास ऐसे टिकट हैं जो विश्लेषक देख सकता है, वह फिर भी दिखती है, ताकि फ़ोल्डरों का जोड़ सही रहे। एडमिनिस्ट्रेटर को हमेशा हर टीम दिखती है।',
            'watch_heading' => 'टिकट वॉच करना',
            'watch_help' => 'टिकट के वॉचरों को किस बारे में बताया जाता है। हर वॉचर की अपनी सूचना सेटिंग्स इसके ऊपर फिर भी लागू रहती हैं।',
            'watch_inactive_label' => 'जब कोई वॉचर निष्क्रिय किया जाए',
            'watch_inactive_stop' => 'उन्हें बताना बंद करें - उनके वॉच रखें, अगर वे लौट आएँ',
            'watch_inactive_remove' => 'जिन टिकटों को वे वॉच करते हैं उन सब से उन्हें हटा दें',
            'watch_inactive_help' => 'निष्क्रिय विश्लेषक को कभी कुछ नहीं बताया जाता। बंद करें उनके वॉच को नज़र से दूर रखता है और विश्लेषक के फिर सक्रिय होने पर लौटा देता है; हटाएँ विश्लेषक के निष्क्रिय होते ही उन्हें मिटा देता है। हटाना इसे सहेजने के समय से लागू होता है।',
            'watch_event_ticket_reply_received' => 'अनुरोधकर्ता जवाब देता है',
