            'mode_auto_help' => 'टिकट के किसी भी बंद स्थिति में जाने पर एक सर्वेक्षण अपने आप भेजा जाता है।',
            'mode_manual' => 'केवल मैनुअल',
            'mode_manual_help' => 'जब विश्लेषक पूछना चाहते हैं तो वे टिकट टूलबार से <em>Feedback</em> पर क्लिक करते हैं।',
            'delay_help' => 'बंद होने के बाद भेजने से पहले इतने मिनट प्रतीक्षा करें। <code>0</code> = तुरंत। उपयोगी अगर आप चाहते हैं कि रेट करने के लिए कहे जाने से पहले उपयोगकर्ता यह पुष्टि कर ले कि फ़िक्स असल में टिका रहा।',
            'reminder' => 'सर्वे का जवाब न मिलने पर एक अनुस्मारक भेजें',
            'reminder_hours' => 'इतने घंटे बाद याद दिलाएँ',
            'reminder_help' => 'अधिकतम एक अनुस्मारक, ईमेल से, उसी लिंक के साथ - इसलिए कोई भी ईमेल काम करता है और केवल एक रेटिंग रखी जाती है। केवल ईमेल से भेजे गए सर्वे को याद दिलाया जाता है, चाहे वे बंद करने पर गए हों या <strong>Feedback</strong> बटन से। अगर अनुस्मारक के समय टिकट फिर खुला हो या ट्रैश में हो तो नहीं भेजा जाता। अगर आपके पास <strong>CSAT reminder</strong> ईमेल टेम्पलेट है तो वही उपयोग होता है, नहीं तो सर्वे टेम्पलेट ही दोबारा। यह <em>Delayed satisfaction surveys and reminders</em> बैकग्राउंड जॉब से भेजा जाता है। इसे चालू करने से पुराने सर्वे के लिए याद नहीं दिलाई जाती: केवल उनके लिए जिनका अनुस्मारक अब से देय होगा।',
            'one_per_ticket' => 'प्रति टिकट एक सर्वेक्षण',
            'one_per_ticket_help' => 'चालू होने पर, फिर से खोले गए और फिर बंद किए गए टिकट को दूसरा सर्वेक्षण तभी मिलता है जब कोई विश्लेषक इसे मैन्युअल रूप से ट्रिगर करे &mdash; यह किसी अस्थिर टिकट को सर्वे-स्पैम होने से रोकता है।',
            'in_channel' => 'चैट ग्राहकों से उनकी चैट में ही पूछें',
            'in_channel_help' => 'WhatsApp, Telegram, Slack, Teams या Mattermost पर लिखने वाले ग्राहक से ईमेल की जगह उसी चैट में पूछा जाता है &mdash; जहाँ ऐप में बटन हैं वहाँ बटन, जहाँ नहीं हैं वहाँ &ldquo;1 से 5 लिखकर उत्तर दें&rdquo;। WhatsApp पर केवल तब तक जब तक उसकी 24 घंटे की विंडो खुली है; अन्यथा, और चैट संदेश विफल होने पर, ईमेल सर्वेक्षण इस्तेमाल होता है।',
