            'r1_s' => 'इनबॉक्स पर कोई SLA pill नहीं दिखती',
            'r1_c' => '<code>Enforce SLAs from</code> खाली है, प्राथमिकता में कोई लक्ष्य सेट नहीं है, या टिकट कटऑफ से पहले का है।',
            'r2_s' => 'SLA उल्लंघन दिखा रहा है लेकिन विश्लेषक ने लक्ष्य के भीतर जवाब दिया था',
            'r2_c' => 'प्राथमिकता परिवर्तन इतिहास जाँचें &mdash; यदि प्राथमिकता बीच में अपग्रेड की गई थी और व्यवहार "Forward" (डिफ़ॉल्ट) पर सेट है, तो अर्जित समय आगे बढ़ जाता है।',
            'r3_s' => 'उल्लंघन सूचनाएँ नहीं भेजी जा रहीं',
            'r3_c' => '(1) कोई नियम कॉन्फ़िगर नहीं है। (2) Cron job शेड्यूल नहीं है। (3) नियम कॉन्फ़िगर हैं लेकिन प्राप्तकर्ता तय नहीं हो पा रहे (कोई असाइनी नहीं, विभाग टीमों में ईमेल वाला कोई सदस्य नहीं)। प्रति-रन सारांश के लिए Cron Activity पैनल जाँचें।',
            'r4_s' => 'Cron चलता है लेकिन "no matching rule" रिपोर्ट करता है',
