            'r5_s' => 'Watchtower "N tickets paused over 24h" दिखाता है',
            'r5_c' => 'टिकट किसी pause-SLA स्थिति में पड़े हैं। या तो किसी ने जानबूझकर उन्हें रोका और भूल गया, या कोई On Hold का उपयोग SLA से बचने के लिए कर रहा है। हर एक को खोलें और उसे आगे बढ़ाएँ या pause स्थिति हटाएँ।',
            'r6_s' => 'HTTP cron 403 लौटाता है',
