            'r7_s' => 'HTTP cron 429 "Rate limited" लौटाता है',
            'r7_c' => 'पिछला सफल रन <code>sla_cron_min_interval_seconds</code> (डिफ़ॉल्ट 30s) से भी कम समय पहले पूरा हुआ था। इंतज़ार करें या सेटिंग कम करें।',
            'r8_s' => 'HTTP cron 429 "Too many failed attempts" लौटाता है',
            'r8_c' => 'इस IP ने पिछले एक घंटे में 10 से ज़्यादा गलत-टोकन प्रयास किए हैं। 1 घंटा इंतज़ार करें या विफलताएँ हटाएँ: <code>DELETE FROM sla_cron_runs WHERE client_ip = \'...\' AND outcome = \'auth_failed\'</code>।',
            'tip' => 'Cron सेटअप की गहन तकनीकी जानकारी के लिए, जिसमें Linux उदाहरण और रिमोट-शेड्यूलर इंटीग्रेशन शामिल हैं, FreeITSM इंस्टॉल डायरेक्टरी में <code>docs/sla-cron-setup.md</code> देखें।',
